<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Masukkan Token — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#1f2937}*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:22px;display:grid;place-items:center;background:radial-gradient(circle at 8% 18%,#a0b4d152 0 110px,transparent 111px),radial-gradient(circle at 91% 85%,#365d9230 0 210px,transparent 211px),linear-gradient(135deg,#f5f7fa,#e8eef7);overflow:hidden}.ring{position:fixed;border:1px solid #365d9226;border-radius:50%;width:350px;height:350px;right:-120px;top:-110px}.ring:after{content:"";position:absolute;inset:26px;border:1px solid #a0b4d14d;border-radius:50%}.shell{position:relative;width:min(100%,510px)}.back{position:absolute;inset:16px -18px -16px;background:#365d9217;border-radius:30px;transform:rotate(3deg)}.card{position:relative;background:#fffd;border:1px solid #fff;border-radius:25px;padding:33px;box-shadow:0 22px 45px #23395d18}.top{display:flex;justify-content:space-between;align-items:center}.mark{display:grid;place-items:center;width:52px;height:52px;border-radius:16px;background:#e8eef7;color:#23395d;font-size:25px}.out{border:0;background:#f5f7fa;color:#64748b;padding:9px 12px;border-radius:9px;font:600 12px Inter;cursor:pointer}.eyebrow{color:#365d92;font-size:12px;font-weight:800;letter-spacing:1px;text-transform:uppercase;margin:24px 0 7px}.card h1{font-size:27px;letter-spacing:-.8px;margin:0}.muted{color:#64748b;line-height:1.65}.steps{display:flex;gap:8px;margin:20px 0}.step{flex:1;padding:10px;border-radius:10px;background:#f5f7fa;color:#64748b;font-size:11px}.step b{display:block;color:#23395d;font-size:15px;margin-bottom:4px}.step.active{background:#e8eef7}.field{display:grid;gap:8px;margin:22px 0 13px;font-weight:700;font-size:13px}input{border:1px solid #cbd5e1;border-radius:12px;padding:15px;font:800 21px Inter;text-align:center;letter-spacing:5px;color:#23395d;text-transform:uppercase;outline:0}input:focus{box-shadow:0 0 0 4px #a0b4d14f;border-color:#365d92}button.go{width:100%;border:0;border-radius:12px;padding:15px;background:#23395d;color:#fff;font:800 15px Inter;cursor:pointer;box-shadow:0 9px 17px #23395d33}.error{color:#991b1b;background:#fff0f0;padding:10px;border-radius:9px;font-size:13px}</style></head><body><i class="ring"></i><main class="shell"><i class="back"></i><section class="card"><header class="top"><i class="mark">⌘</i><form method="post" action="{{ route('logout') }}">@csrf<button class="out">Keluar ↪</button></form></header><p class="eyebrow">Akses Ujian</p><h1>Masukkan Token Ujian</h1><p class="muted">Gunakan token yang dibagikan guru. Token yang sama selalu membuka ujian yang sama.</p><section class="steps"><article class="step"><b>01</b>Masukkan token</article><article class="step active"><b>02</b>Siapkan diri</article><article class="step"><b>03</b>Kerjakan ujian</article></section>@if($errors->any())<p class="error">{{ $errors->first() }}</p>@endif<form method="post" action="{{ route('student.token.submit') }}">@csrf<div class="field"><label for="token">TOKEN UJIAN</label><input id="token" name="token" value="{{ old('token') }}" maxlength="32" autofocus required></div><button class="go">Lanjut ke Persiapan →</button></form></section></main></body></html>
